mapper.select:
SELECT DATE_FORMAT(h.start_time, '%m-%d') as dateStr, COUNT(*) as countVal FROM sf_deployment_history h LEFT JOIN sf_deployment d ON h.deployment_id = d.id
h.start_time >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY) ${params.dataScope}
GROUP BY DATE_FORMAT(h.start_time, '%m-%d') ORDER BY dateStr ASC

SELECT h.status as name, COUNT(*) as value FROM sf_deployment_history h LEFT JOIN sf_deployment d ON h.deployment_id = d.id
${params.dataScope}
GROUP BY h.status

SELECT h.*, s.title as deploymentTitle FROM sf_deployment_history h LEFT JOIN sf_deployment s ON h.deployment_id = s.id
${params.dataScope}
ORDER BY h.start_time DESC LIMIT #{limit}
